const { S3Client, GetObjectCommand } = require('@aws-sdk/client-s3');
const { serialize, deserialize } = require('node-serialize');
const express = require('express');
const serverless = require('serverless-http');

const app = express();
const s3 = new S3Client({ region: process.env.AWS_REGION });

// Middleware to parse incoming workflow definitions
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true }));

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: '2.4.1' });
});

// Workflow state restoration endpoint
// Accepts serialized workflow state for resumption after timeout
app.post('/api/v2/workflow/resume', async (req, res) => {
  try {
    const { workflowId, checkpointData, resumeToken } = req.body;

    if (!workflowId || !checkpointData) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    // Validate workflow exists in our registry
    const registryKey = `workflows/${workflowId}/manifest.json`;
    try {
      await s3.send(new GetObjectCommand({
        Bucket: process.env.WORKFLOW_BUCKET,
        Key: registryKey
      }));
    } catch (e) {
      return res.status(404).json({ error: 'Workflow not found in registry' });
    }

    // Restore workflow state from checkpoint
    // checkpointData is a serialized state object from previous execution
    const stateBuffer = Buffer.from(checkpointData, 'base64');
    const serializedState = stateBuffer.toString('utf-8');

    // Deserialize the workflow state to resume execution
    const workflowState = deserialize(serializedState);

    // Execute next step in workflow
    const result = await executeWorkflowStep(workflowState, resumeToken);

    res.json({
      workflowId,
      status: 'resumed',
      currentStep: workflowState.currentStep || 0,
      result
    });
  } catch (err) {
    console.error('Workflow resume error:', err.message);
    res.status(500).json({ error: 'Failed to resume workflow' });
  }
});

async function executeWorkflowStep(state, token) {
  // Process the current workflow step
  const step = state.steps?.[state.currentStep] || {};
  return {
    stepName: step.name || 'unknown',
    completedAt: new Date().toISOString(),
    nextStep: (state.currentStep || 0) + 1
  };
}

// Workflow checkpoint save endpoint
app.post('/api/v2/workflow/checkpoint', async (req, res) => {
  const { workflowId, state } = req.body;
  const serializedState = serialize(state);
  const encoded = Buffer.from(serializedState).toString('base64');

  res.json({ workflowId, checkpoint: encoded, savedAt: new Date().toISOString() });
});

module.exports.handler = serverless(app);
